import{z as i,x as A,o as B,c as d,q as t,j as s,D as e,d as E,s as o,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"BBR 对照","description":"","frontmatter":{"title":"BBR 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bbr.md","filePath":"cs/bbr.md","lastUpdated":1791413859000}'),p={name:"cs/bbr.md"};function C(c,a,T,D,m,R){const r=A("Mermaid");return B(),d("div",null,[a[2]||(a[2]=t('<h1 id="bbr-对照" tabindex="-1">BBR 对照 <a class="header-anchor" href="#bbr-对照" aria-label="Permalink to &quot;BBR 对照&quot;">​</a></h1><div class="epigraph"><p>把速率对准估计的瓶颈带宽，把飞行数据对准最小 RTT 下的 BDP；拥塞信号从「队列溢出」转到「模型」。 </p><footer>—— Cardwell, Cheng, Gunn, Jacobson and Yeganeh, BBR: Congestion-Based Congestion Control, ACM Queue 2016</footer></div><p><a href="/cs/reno-cubic">上一课</a>在丢包驱动下比较了 Reno 与 Cubic。本课不重画立方曲线。缺口是：浅缓冲或无线误码时，丢包不等于瓶颈满；深缓冲时丢包来得太晚，队列已经很大。BBR 用交付率估带宽、用最小 RTT 估延迟，对照而非替换 TCP 可靠性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AIMD 把溢出当探针。缓冲很小则永远探溢；缓冲很大则延迟主导。BBR 的缺口是控制量改成两个估计：瓶颈带宽 BtlBw、往返传播 RTprop，发送速率与 <code>cwnd</code> 按 BDP 操作，并周期性探测是否变高/变低。本课不把版本号演进（BBR v2/v3）写成标准战争。</p><p><span class="marginnote">BBR 仍跑在 TCP（或 QUIC）上，序号与重传不变。它改变 pacing 与窗口，不改变 RFC 793 的字节流合同。</span></p><p><span class="marginnote">直觉类比：AIMD 像「水漫出来才知道关小」，BBR 像调水龙头——稍微拧大一点，看水流是否真的变快：变快说明管子还能承受，不变快就把多拧的收回来。它始终盯着「管子多粗」和「水走完全程要多久」这两个数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>探测带宽：以略超估计的速率发，看交付率是否上升。探测 RTT：短暂降速看最小 RTT 是否更小。稳态：pacing 接近 BtlBw，飞行数据略高于 BDP 以保持管道满。与 Cubic 对照：后者填缓冲直到丢；BBR 声称把队列压在小幅度。共存时可能不公平，这是对照的边界，不是本课调参。</p>',9)),(B(),s(l,null,{default:e(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACK%5B%22%E4%BA%A4%E4%BB%98%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20BW%5B%22%E4%BC%B0%E8%AE%A1%E7%93%B6%E9%A2%88%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20ACK%20--%3E%20MIN%5B%22%E4%BC%B0%E8%AE%A1%E6%9C%80%E5%B0%8F%20RTT%22%5D%0A%20%20BW%20--%3E%20PACE%5B%22%E6%8C%89%E6%A8%A1%E5%9E%8B%20pacing%22%5D%0A%20%20MIN%20--%3E%20PACE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"模型控制把「共享队列的博弈」从丢包博弈改成估计博弈。估计错（路径变化、聚合链路）会过冲或欠载。端到端正确性仍靠校验与重传；BBR 不提供新的 CIA 性质。后课 QUIC 可以换传输实现，仍可跑同类控制。",-1)),(B(),s(l,null,{default:e(()=>[o(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SS%5B%22%E7%A8%B3%E6%80%81%3A%20pacing%20%E7%BA%A6%E7%AD%89%E4%BA%8E%20BtlBw%22%5D%20--%3E%20PB%5B%22%E5%91%A8%E6%9C%9F%E8%AF%95%E6%8E%A2%3A%201.25%20%E5%80%8D%E9%80%9F%E5%8F%91%E4%B8%80%E9%98%B5%22%5D%0A%20%20PB%20--%3E%20Q%7B%22%E4%BA%A4%E4%BB%98%E7%8E%87%E8%B7%9F%E7%9D%80%E4%B8%8A%E5%8D%87%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20HI%5B%22%E5%B8%A6%E5%AE%BD%E7%9C%9F%E7%9A%84%E5%8F%98%E9%AB%98%2C%20%E5%B7%A1%E8%88%AA%E5%88%B0%E6%96%B0%E5%80%BC%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20DL%5B%22%E9%99%8D%E5%88%B0%200.75%20%E5%80%8D%E6%8E%92%E6%B0%B4%2C%20%E6%94%B6%E5%9B%9E%E5%A4%9A%E5%8F%91%E7%9A%84%22%5D%0A%20%20DL%20--%3E%20RT%5B%22%E6%8E%A2%E6%B5%8B%20RTT%3A%20%E7%9F%AD%E6%9A%82%E9%99%8D%E9%80%9F%E6%89%BE%E6%9C%80%E5%B0%8F%E5%80%BC%22%5D%0A%20%20RT%20--%3E%20SS%0A%20%20HI%20--%3E%20SS%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字实例：链路 100 Mb/s、RTT 40 ms，则 BDP \\(= 10^8 \\times 0.04 / 8 = 0.5\\) MB。BBR 巡航时把飞行数据维持在略高于 0.5 MB（乘个保管道满的小系数）；Reno 若靠丢包探窗口，可能先把几 MB 的缓冲灌满才回头，队列与延迟都大了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 XCP 一类路由器协助协议当主干，不把内核开关当教材命令。应用层名字如何映射到 IP，后课 DNS。</p><p><span class="marginnote">常见误区：初学者容易以为 BBR 是一套新传输协议。它仍跑在普通 TCP 或 QUIC 之上，序号、确认、重传一字不改；换的只是「什么时候发多少」——pacing 节奏与窗口大小，字节流合同还是原来那份。</span></p><p>后课默认：拥塞控制可以不把丢包当唯一信号。人可读的主机名是另一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BBR 用带宽与最小 RTT 建模，对照 Reno/Cubic 的丢包 AIMD。</li><li>可靠性合同不变。</li><li>名字解析后课 DNS。</li><li>出处：Cardwell 等, <em>ACM Queue</em> 2016；对照 RFC 5681；Kurose and Ross。</li></ul>',7))])}const h=i(p,[["render",C]]);export{u as __pageData,h as default};
